import json

def load(path):
    blocked = {"status": "blocked", "resume": None}
    try:
        value = json.loads(path.read_text())
    except (OSError, ValueError):
        return blocked
    if isinstance(value, dict) and value.get("status") == "ready" and isinstance(value.get("resume"), str) and value["resume"]:
        return value
    return blocked
